-- AgentOS demo dataset: synthetic Q1-Q3 2026 sales data
-- Shows a Q3 revenue decline driven by a competitor discount campaign
-- starting July 2026, concentrated in Home & Office and Electronics.

DROP TABLE IF EXISTS sales;
CREATE TABLE sales (
    id INTEGER PRIMARY KEY,
    sale_date DATE NOT NULL,
    product VARCHAR(100) NOT NULL,
    category VARCHAR(50) NOT NULL,
    region VARCHAR(50) NOT NULL,
    salesperson VARCHAR(100) NOT NULL,
    quantity INTEGER NOT NULL,
    unit_price NUMERIC(10,2) NOT NULL,
    revenue NUMERIC(12,2) NOT NULL,
    quarter VARCHAR(2) NOT NULL,
    year INTEGER NOT NULL
);

DROP TABLE IF EXISTS competitor_notes;
CREATE TABLE competitor_notes (
    id SERIAL PRIMARY KEY,
    note_date DATE NOT NULL,
    competitor VARCHAR(100) NOT NULL,
    note TEXT NOT NULL
);


